import { useState, useEffect } from "react";
import { Menu, X, HelpCircle } from "lucide-react";
import { Link, useLocation } from "react-router-dom";

const navLinks = [
  { label: "Home", href: "/", isRoute: true },
  { label: "Empresa", href: "/quem-somos", isRoute: true },
  { label: "Produtos", href: "/catalogo", isRoute: true },
  { label: "Receitas", href: "/receitas", isRoute: true },
  { label: "Clientes", href: "/#clientes", isRoute: false },
  { label: "Contato", href: "/contato", isRoute: true },
  { label: "Eventos", href: "/eventos", isRoute: true },
  { label: "FAQ", href: "/faq", isRoute: true },
  { label: "Blog", href: "/blog", isRoute: true },
];

export default function Navbar() {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const location = useLocation();
  const isHome = location.pathname === "/";

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 50);
    };
    window.addEventListener("scroll", handleScroll, { passive: true });
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  // Reset mobile menu on route change
  useEffect(() => {
    setIsOpen(false);
  }, [location.pathname]);

  const handleNavClick = (
    e: React.MouseEvent<HTMLAnchorElement>,
    href: string,
    isRoute: boolean
  ) => {
    if (isRoute) return; // Let Link handle it
    e.preventDefault();
    if (isHome) {
      const hash = href.replace("/", "");
      const target = document.querySelector(hash);
      if (target) {
        target.scrollIntoView({ behavior: "smooth" });
      }
    } else {
      window.REACT_APP_NAVIGATE?.(href);
    }
    setIsOpen(false);
  };

  const navbarBg = isHome
    ? scrolled
      ? "bg-white shadow-md"
      : "bg-transparent"
    : "bg-white shadow-sm";

  const textColor = isHome && !scrolled ? "text-white" : "text-gray-800";
  const logoFilter = isHome && !scrolled ? "brightness-0 invert" : "";

  return (
    <nav
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${navbarBg}`}
    >
      <div className="flex items-center justify-between px-4 md:px-8 lg:px-12 h-16 md:h-20">
        {/* Logo */}
        <Link to="/" className="flex items-center z-10" onClick={() => setIsOpen(false)}>
          <img
            src="https://storage.readdy-site.link/project_files/19bab42f-a1e6-4ada-9847-319a0f0abd49/990f65d6-1980-41e2-92ce-3e3f19d07be9_ChatGPT-Image-1-de-mai.-de-2026-08_52_14.png?v=5b0f463886cc8f5648bd6a4cec408a8d"
            alt="Tempero Regina"
            className={`h-16 md:h-20 lg:h-24 w-auto object-contain transition-all duration-300 ${logoFilter}`}
          />
        </Link>

        {/* Desktop Nav */}
        <div className="hidden md:flex items-center gap-5 lg:gap-7">
          {navLinks.map((link) =>
            link.isRoute ? (
              <Link
                key={link.label}
                to={link.href}
                className={`text-sm font-medium hover:text-regina-red transition-colors whitespace-nowrap ${textColor}`}
              >
                {link.label}
              </Link>
            ) : (
              <a
                key={link.label}
                href={link.href}
                onClick={(e) => handleNavClick(e, link.href, false)}
                className={`text-sm font-medium hover:text-regina-red transition-colors whitespace-nowrap ${textColor}`}
              >
                {link.label}
              </a>
            )
          )}
          <div className="flex items-center gap-2 ml-1">
            <a
              href="https://instagram.com/temperoregina"
              target="_blank"
              rel="noopener noreferrer"
              className={`w-8 h-8 flex items-center justify-center hover:text-regina-red transition-colors ${textColor}`}
              aria-label="Instagram"
            >
              <i className="ri-instagram-line text-lg" />
            </a>
            <a
              href="https://www.facebook.com/TemperoRegina/"
              target="_blank"
              rel="noopener noreferrer"
              className={`w-8 h-8 flex items-center justify-center hover:text-regina-red transition-colors ${textColor}`}
              aria-label="Facebook"
            >
              <i className="ri-facebook-line text-lg" />
            </a>
            <a
              href="https://www.youtube.com/user/TemperoRegina"
              target="_blank"
              rel="noopener noreferrer"
              className={`w-8 h-8 flex items-center justify-center hover:text-regina-red transition-colors ${textColor}`}
              aria-label="YouTube"
            >
              <i className="ri-youtube-line text-lg" />
            </a>
          </div>
        </div>

        {/* Mobile Hamburger */}
        <button
          type="button"
          className="md:hidden w-10 h-10 flex items-center justify-center z-10"
          onClick={() => setIsOpen(!isOpen)}
          aria-label="Menu"
        >
          {isOpen ? (
            <X className="w-6 h-6 text-regina-red" />
          ) : (
            <Menu className={`w-6 h-6 ${isHome && !scrolled ? "text-white" : "text-regina-red"}`} />
          )}
        </button>
      </div>

      {/* Mobile Menu */}
      <div
        className={`md:hidden bg-white border-t border-gray-100 overflow-hidden transition-all duration-300 ${
          isOpen ? "max-h-[28rem] opacity-100" : "max-h-0 opacity-0"
        }`}
      >
        <div className="px-4 py-3 space-y-1">
          {navLinks.map((link) =>
            link.isRoute ? (
              <Link
                key={link.label}
                to={link.href}
                className="block py-2 text-sm font-medium text-gray-800 hover:text-regina-red transition-colors"
                onClick={() => setIsOpen(false)}
              >
                {link.label}
              </Link>
            ) : (
              <a
                key={link.label}
                href={link.href}
                onClick={(e) => handleNavClick(e, link.href, false)}
                className="block py-2 text-sm font-medium text-gray-800 hover:text-regina-red transition-colors"
              >
                {link.label}
              </a>
            )
          )}
          <div className="flex items-center gap-4 pt-3 border-t border-gray-100">
            <a
              href="https://instagram.com/temperoregina"
              target="_blank"
              rel="noopener noreferrer"
              className="w-8 h-8 flex items-center justify-center text-regina-red"
              aria-label="Instagram"
            >
              <i className="ri-instagram-line text-lg" />
            </a>
            <a
              href="https://www.facebook.com/TemperoRegina/"
              target="_blank"
              rel="noopener noreferrer"
              className="w-8 h-8 flex items-center justify-center text-regina-red"
              aria-label="Facebook"
            >
              <i className="ri-facebook-line text-lg" />
            </a>
            <a
              href="https://www.youtube.com/user/TemperoRegina"
              target="_blank"
              rel="noopener noreferrer"
              className="w-8 h-8 flex items-center justify-center text-regina-red"
              aria-label="YouTube"
            >
              <i className="ri-youtube-line text-lg" />
            </a>
          </div>
        </div>
      </div>
    </nav>
  );
}